CUSTOM_CSS = "\n    <style>\n    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n    \n    * {\n        font-family: 'Inter', sans-serif;\n    }\n    \n    .main-header {\n        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n        padding: 2rem;\n        border-radius: 20px;\n        color: white;\n        text-align: center;\n        margin-bottom: 2rem;\n        box-shadow: 0 10px 30px rgba(0,0,0,0.1);\n        position: relative;\n        overflow: hidden;\n    }\n    \n    .main-header::before {\n        content: '';\n        position: absolute;\n        top: -50%;\n        left: -50%;\n        width: 200%;\n        height: 200%;\n        background: linear-gradient(45deg, transparent, rgba(255,255,255,0.1), transparent);\n        transform: rotate(45deg);\n        animation: shine 3s infinite;\n    }\n    \n    @keyframes shine {\n        0% { transform: translateX(-100%) translateY(-100%) rotate(45deg); }\n        100% { transform: translateX(100%) translateY(100%) rotate(45deg); }\n    }\n    \n    .hero-quote {\n        background: linear-gradient(135deg, #ff6b6b 0%, #ff8e53 100%);\n        padding: 2rem;\n        border-radius: 15px;\n        color: white;\n        text-align: center;\n        margin: 2rem 0;\n        box-shadow: 0 8px 25px rgba(0,0,0,0.15);\n        border-left: 5px solid rgba(255,255,255,0.3);\n    }\n    \n    .metric-card {\n        background: white;\n        padding: 1.5rem;\n        border-radius: 15px;\n        box-shadow: 0 5px 15px rgba(0,0,0,0.08);\n        border-left: 4px solid #667eea;\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\n    }\n    \n    .metric-card:hover {\n        transform: translateY(-5px);\n        box-shadow: 0 8px 25px rgba(0,0,0,0.15);\n    }\n    \n    .emergency-alert {\n        background: linear-gradient(135deg, #ff4757 0%, #ff3742 100%);\n        color: white;\n        padding: 1.5rem;\n        border-radius: 15px;\n        margin: 1rem 0;\n        animation: pulse 2s infinite;\n        border: 3px solid rgba(255,255,255,0.3);\n    }\n    \n    @keyframes pulse {\n        0% { box-shadow: 0 0 0 0 rgba(255, 71, 87, 0.4); }\n        70% { box-shadow: 0 0 0 10px rgba(255, 71, 87, 0); }\n        100% { box-shadow: 0 0 0 0 rgba(255, 71, 87, 0); }\n    }\n    \n    .success-alert {\n        background: linear-gradient(135deg, #2ed573 0%, #1e90ff 100%);\n        color: white;\n        padding: 1.5rem;\n        border-radius: 15px;\n        margin: 1rem 0;\n        border-left: 5px solid rgba(255,255,255,0.3);\n    }\n    \n    .user-type-badge {\n        display: inline-block;\n        padding: 0.5rem 1rem;\n        border-radius: 20px;\n        font-size: 0.85rem;\n        font-weight: 600;\n        margin: 0.5rem;\n    }\n    \n    .patient-badge { background: linear-gradient(135deg, #74b9ff 0%, #0984e3 100%); color: white; }\n    .student-badge { background: linear-gradient(135deg, #55a3ff 0%, #003d82 100%); color: white; }\n    .professional-badge { background: linear-gradient(135deg, #fd79a8 0%, #e84393 100%); color: white; }\n    \n    .stButton > button {\n        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n        color: white;\n        border: none;\n        border-radius: 10px;\n        padding: 0.75rem 1.5rem;\n        font-weight: 600;\n        transition: all 0.3s ease;\n        box-shadow: 0 4px 15px rgba(0,0,0,0.1);\n    }\n    \n    .stButton > button:hover {\n        transform: translateY(-2px);\n        box-shadow: 0 6px 20px rgba(0,0,0,0.15);\n    }\n    \n    .notification-card {\n        background: linear-gradient(135deg, #ffeaa7 0%, #fdcb6e 100%);\n        padding: 1rem;\n        border-radius: 10px;\n        margin: 0.5rem 0;\n        border-left: 4px solid #e17055;\n    }\n    \n    .voice-controls {\n        background: rgba(255,255,255,0.1);\n        padding: 1rem;\n        border-radius: 10px;\n        margin: 1rem 0;\n        backdrop-filter: blur(10px);\n    }\n    \n    .map-container {\n        border-radius: 15px;\n        overflow: hidden;\n        box-shadow: 0 8px 25px rgba(0,0,0,0.1);\n    }\n    </style>\n    "


